export interface GitHubRepositoryRef {
  owner: string;
  repo: string;
}

const repositoryName = /^[A-Za-z0-9_.-]+$/;

export function parseTeamRepositoryMap(
  value: string | undefined,
): ReadonlyMap<string, GitHubRepositoryRef> {
  if (!value?.trim()) return new Map();

  let input: unknown;
  try {
    input = JSON.parse(value);
  } catch {
    throw new Error("LINEAR_TEAM_REPOSITORIES must be valid JSON.");
  }

  if (!isRecord(input) || Array.isArray(input)) {
    throw new Error(
      "LINEAR_TEAM_REPOSITORIES must be a JSON object mapping team IDs to owner/repo.",
    );
  }

  const entries = Object.entries(input).map(([teamId, repository]) => {
    if (!teamId.trim() || typeof repository !== "string") {
      throw new Error(
        "LINEAR_TEAM_REPOSITORIES must map non-empty team IDs to owner/repo strings.",
      );
    }
    return [teamId, parseRepository(repository)] as const;
  });

  return new Map(entries);
}

export function repositoryForTeam(
  teamId: string,
  value = process.env.LINEAR_TEAM_REPOSITORIES,
): GitHubRepositoryRef | undefined {
  return parseTeamRepositoryMap(value).get(teamId);
}

export function parseRepository(value: string): GitHubRepositoryRef {
  const parts = value.trim().split("/");
  if (
    parts.length !== 2 ||
    !parts[0] ||
    !parts[1] ||
    !repositoryName.test(parts[0]) ||
    !repositoryName.test(parts[1])
  ) {
    throw new Error(`Invalid GitHub repository mapping: ${value}`);
  }
  return { owner: parts[0], repo: parts[1] };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object";
}

