import { defineTool } from "@flue/runtime";
import * as v from "valibot";
import { createGitHubClient, getDefaultBranch } from "../shared/github-client.ts";
import type { GitHubRepositoryRef } from "../shared/repository-config.ts";

const MAX_DIRECTORY_ENTRIES = 200;
const MAX_SEARCH_RESULTS = 30;
const MAX_FILE_BYTES = 100_000;

export function repositoryReadTools(ref: GitHubRepositoryRef) {
  const repository = `${ref.owner}/${ref.repo}`;

  return [
    defineTool({
      name: "list_repository_files",
      description:
        "List files and directories at one path on the mapped GitHub repository's default branch. Use this to understand repository structure. The repository is fixed by the Linear team.",
      input: v.object({
        path: v.optional(v.pipe(v.string(), v.maxLength(500))),
      }),
      async run({ data }) {
        const path = normalizeAndValidatePath(data.path ?? "");
        const client = createGitHubClient();
        const branch = await getDefaultBranch(client, ref);
        const response = await client.rest.repos.getContent({
          owner: ref.owner,
          repo: ref.repo,
          path,
          ref: branch,
        });
        if (!Array.isArray(response.data)) {
          throw new Error(`${path || "."} is not a directory.`);
        }
        const entries = response.data
          .filter((entry) => isAllowedPath(entry.path))
          .slice(0, MAX_DIRECTORY_ENTRIES)
          .map((entry) => ({
            name: entry.name,
            path: entry.path,
            type: entry.type,
          }));
        return {
          output: {
            repository,
            branch,
            path: path || ".",
            entries,
            truncated: response.data.length > entries.length,
          },
        };
      },
    }),
    defineTool({
      name: "search_repository",
      description:
        "Search for literal code or identifiers in the mapped GitHub repository. Use focused terms from the issue, then read promising files. The repository is fixed by the Linear team.",
      input: v.object({
        query: v.pipe(v.string(), v.minLength(2), v.maxLength(100)),
      }),
      async run({ data }) {
        const query = validateSearchQuery(data.query);
        const client = createGitHubClient();
        const response = await client.rest.search.code({
          q: `\"${query}\" repo:${repository}`,
          per_page: MAX_SEARCH_RESULTS,
        });
        const matches = response.data.items
          .filter((item) => isAllowedPath(item.path))
          .map((item) => ({ path: item.path, url: item.html_url }));
        return {
          output: {
            repository,
            query,
            matches,
            totalCount: response.data.total_count,
            incomplete: response.data.incomplete_results,
          },
        };
      },
    }),
    defineTool({
      name: "read_repository_file",
      description:
        "Read one text file from the mapped GitHub repository's default branch. Read only files found through listing or search and use paths in the strengthened issue only when supported by the content.",
      input: v.object({
        path: v.pipe(v.string(), v.minLength(1), v.maxLength(500)),
      }),
      async run({ data }) {
        const path = normalizeAndValidatePath(data.path);
        const client = createGitHubClient();
        const branch = await getDefaultBranch(client, ref);
        const response = await client.rest.repos.getContent({
          owner: ref.owner,
          repo: ref.repo,
          path,
          ref: branch,
        });
        if (Array.isArray(response.data) || response.data.type !== "file") {
          throw new Error(`${path} is not a file.`);
        }
        if (response.data.size > MAX_FILE_BYTES) {
          throw new Error(`${path} exceeds the ${MAX_FILE_BYTES}-byte read limit.`);
        }
        if (response.data.encoding !== "base64" || !response.data.content) {
          throw new Error(`${path} cannot be read as inline text content.`);
        }
        const content = Buffer.from(response.data.content, "base64").toString("utf8");
        if (Buffer.byteLength(content, "utf8") > MAX_FILE_BYTES || content.includes("\0")) {
          throw new Error(`${path} is too large or is not a text file.`);
        }
        return { output: { repository, branch, path, content } };
      },
    }),
  ] as const;
}

export function normalizeAndValidatePath(input: string): string {
  const path = input.trim().replace(/^\.\//, "");
  if (
    path.startsWith("/") ||
    path.includes("\\") ||
    path.split("/").some((segment) => segment === ".." || segment === ".") ||
    !isAllowedPath(path)
  ) {
    throw new Error("Repository path is outside the allowed read boundary.");
  }
  return path;
}

export function isAllowedPath(path: string): boolean {
  const segments = path.toLowerCase().split("/").filter(Boolean);
  return !segments.some((segment) => {
    return (
      segment === ".git" ||
      segment === ".ssh" ||
      segment === ".npmrc" ||
      segment === ".pypirc" ||
      segment === ".netrc" ||
      segment === "credentials" ||
      segment.startsWith(".env") ||
      /(?:^|[._-])(secret|secrets|credential|credentials)(?:[._-]|$)/.test(segment) ||
      /\.(?:pem|key|p12|pfx|keystore|jks)$/.test(segment)
    );
  });
}

export function validateSearchQuery(input: string): string {
  const query = input.trim();
  if (
    query.length < 2 ||
    /[\r\n\"]/.test(query) ||
    /(?:^|\s)(?:repo|org|user):/i.test(query) ||
    /\b(?:OR|AND|NOT)\b/.test(query)
  ) {
    throw new Error("Use one literal search term without GitHub query operators.");
  }
  return query;
}

